[metadata] {"type": "create", "filePath": "/app/src/main/java/com/example/contact/MessageStore.java", "content": "package com.example.contact;

import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;

import com.vaadin.flow.server.VaadinSession;

/**
 * The messages sent so far, newest first. Kept in the Vaadin session, so the
 * list outlives a single visit to the contact view without being shared with
 * other users.
 */
public class MessageStore implements Serializable {

    private final List<Message> messages = new ArrayList<>();

    /**
     * The store of the current session, created on first use.
     */
    public static MessageStore current() {
        VaadinSession session = VaadinSession.getCurrent();
        if (session == null) {
            // No session to remember anything in, e.g. outside a request.
            return new MessageStore();
        }
        MessageStore store = session.getAttribute(MessageStore.class);
        if (store == null) {
            store = new MessageStore();
            session.setAttribute(MessageStore.class, store);
        }
        return store;
    }

    /**
     * Adds a message as the newest one.
     */
    public void add(Message message) {
        messages.add(0, message);
    }

    /**
     * The messages, newest first.
     */
    public List<Message> messages() {
        return new ArrayList<>(messages);
    }
}
