+        if (!emailValue.isEmpty()
+                && !EMAIL_PATTERN.matcher(emailValue).matches()) {
+            invalid(email, EMAIL_INVALID);
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            invalid(email, CONTACT_REQUIRED);
+            valid = false;
+        }
+
+        String messageValue = message.getValue();
+        if (messageValue.isBlank()) {
+            invalid(message, MESSAGE_REQUIRED);
+            valid = false;
+        } else if (messageValue.length() > MESSAGE_MAX_LENGTH) {
+            invalid(message, MESSAGE_TOO_LONG);
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private void invalid(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void clearErrors() {
+        fields.forEach(field -> {
+            field.setInvalid(false);
+            field.setErrorMessage(null);
+        });
+    }
+
+    private void clearForm() {
+        clearErrors();
+        fields.forEach(TextFieldBase::clear);
+    }
+
+    private void refresh() {
+        sent.setItems(store.messages());
+    }
+
+    private void closeNotification() {
+        if (notification != null) {
+            notification.close();
+            notification = null;
+        }
+    }
+
+    /**
+     * Whether the user has typed something that leaving would lose.
+     */
+    private boolean isDirty() {
+        return fields.stream().anyMatch(field -> !field.getValue().isEmpty());
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (discarding || !isDirty()) {
+            return;
+        }
+        ContinueNavigationAction action = event.postpone();
+
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard your message?");
+        dialog.add(new Paragraph(
+                "The message has not been sent. Leaving now loses what you have written."));
+
+        Button keepEditing = new Button("Keep editing",
+                click -> dialog.close());
+        Button discard = new Button("Discard", click -> {
+            discarding = true;
+            dialog.close();
+            action.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR,
+                ButtonVariant.LUMO_PRIMARY);
+        dialog.getFooter().add(keepEditing, discard);
+
+        dialog.open();
+    }
+}
