+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+import com.microsoft.playwright.Locator;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    private TextFieldElement name() {
+        return TextFieldElement.getByLabel(page, "Name");
+    }
+
+    private EmailFieldElement email() {
+        return EmailFieldElement.getByLabel(page, "Email");
+    }
+
+    private TextFieldElement phone() {
+        return TextFieldElement.getByLabel(page, "Phone");
+    }
+
+    private TextAreaElement message() {
+        return TextAreaElement.getByLabel(page, "Message");
+    }
+
+    private ButtonElement send() {
+        return ButtonElement.getByText(page, "Send");
+    }
+
+    private Locator aboutLink() {
+        return page.locator("a").filter(
+                new Locator.FilterOptions().setHasText("About"));
+    }
+
+    private void fill(String nameValue, String emailValue, String phoneValue,
+            String messageValue) {
+        name().setValue(nameValue);
+        email().setValue(emailValue);
+        phone().setValue(phoneValue);
+        message().setValue(messageValue);
+    }
+
+    /**
+     * Waits for the round trip that a successful send takes. The dramafinder
+     * asserts that poll a component property do not retry on their own, so
+     * anything checked right after a click needs a proper wait first.
+     */
+    private void waitUntilSent(String... cellTexts) {
+        assertThat(page.locator("vaadin-notification-card"))
+                .containsText("Message sent");
+        for (String text : cellTexts) {
+            assertThat(page.locator("vaadin-grid-cell-content").filter(
+                    new Locator.FilterOptions().setHasText(text))).hasCount(1);
+        }
+    }
+
+    @Test
+    void formIsShownAndReadyToUse() {
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(name().getLocator()).isVisible();
+        assertThat(email().getLocator()).isVisible();
+        assertThat(phone().getLocator()).isVisible();
+        assertThat(message().getLocator()).isVisible();
+        name().assertValue("");
+        message().assertValue("");
+        send().assertEnabled();
+        GridElement.get(page).assertEmpty();
+    }
+
+    @Test
+    void emptyFormShowsEveryError() {
+        send().click();
+
+        name().assertInvalid();
+        name().assertErrorMessage("Name is required");
+        email().assertInvalid();
+        email().assertErrorMessage("Give an e-mail address or a phone number");
+        message().assertInvalid();
+        message().assertErrorMessage("Message is required");
+        phone().assertValid();
+        assertThat(page.locator("vaadin-notification-card")).hasCount(0);
+        GridElement.get(page).assertEmpty();
+    }
+
+    @Test
+    void malformedEmailShowsError() {
+        fill("Ada", "not-an-email", "", "Hello");
+
+        send().click();
+
+        email().assertInvalid();
+        email().assertErrorMessage("Enter a valid e-mail address");
+        name().assertValue("Ada");
+        message().assertValue("Hello");
+        GridElement.get(page).assertEmpty();
+    }
+
+    @Test
+    void tooLongMessageShowsError() {
+        fill("Ada", "ada@example.com", "", "x".repeat(501));
+
+        send().click();
+
+        message().assertInvalid();
+        message().assertErrorMessage("Message must be at most 500 characters");
+        GridElement.get(page).assertEmpty();
+    }
+
+    @Test
+    void sendingClearsTheFormAndListsTheMessage() {
+        fill("Ada", "ada@example.com", "040 1234567", "Hello there");
+
+        send().click();
+
+        waitUntilSent("Ada", "Hello there");
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        GridElement grid = GridElement.get(page);
+        grid.assertRowCount(1);
+        grid.assertCellContent(0, 0, "Ada");
+        grid.assertCellContent(0, 1, "Hello there");
+
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+        send().assertDisabled();
+
+        name().setValue("Grace");
+        send().assertEnabled();
+    }
+
+    @Test
+    void phoneAloneIsEnoughAndEnterSends() {
+        fill("Ada", "", "040 1234567", "Sent with Enter");
+
+        message().getInputLocator().press("Enter");
+
+        waitUntilSent("Ada", "Sent with Enter");
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        GridElement.get(page).assertRowCount(1);
+    }
+
+    @Test
+    void newestMessageIsListedFirstAndSurvivesLeaving() {
+        fill("Ada", "ada@example.com", "", "First");
+        send().click();
+        waitUntilSent("First");
+        fill("Grace", "grace@example.com", "", "Second");
+        send().click();
+        waitUntilSent("Second");
+
+        GridElement grid = GridElement.get(page);
+        grid.assertRowCount(2);
+        grid.assertCellContent(0, 0, "Grace");
+        grid.assertCellContent(1, 0, "Ada");
+
+        aboutLink().click();
+        assertThat(page.locator("h1")).hasText("About");
+        page.goBack();
+
+        assertThat(page.locator("vaadin-grid-cell-content").filter(
+                new Locator.FilterOptions().setHasText("Second"))).hasCount(1);
+        GridElement.get(page).assertRowCount(2);
+        GridElement.get(page).assertCellContent(0, 0, "Grace");
+    }
+
+    @Test
+    void emptyFormLeavesWithoutAsking() {
+        page.evaluate("window.pageWasNotReloaded = true");
+
+        aboutLink().click();
+
+        assertThat(page.locator("h1")).hasText("About");
+        assertThat(page.locator("vaadin-dialog-overlay[opened]")).hasCount(0);
+        assertEquals(Boolean.TRUE,
+                page.evaluate("window.pageWasNotReloaded"),
+                "the link should not reload the page");
+    }
+
+    @Test
+    void keepEditingStaysOnTheForm() {
+        name().setValue("Ada");
+        message().setValue("Half written");
+
+        aboutLink().click();
+
+        DialogElement dialog = new DialogElement(page);
+        dialog.assertOpen();
+        ButtonElement.getByText(page, "Keep editing").click();
+
+        assertThat(page.locator("vaadin-dialog-overlay[opened]")).hasCount(0);
+        assertThat(page.locator("h1")).hasText("Contact");
+        name().assertValue("Ada");
+        message().assertValue("Half written");
+        assertThat(page).hasURL(java.util.regex.Pattern.compile(".*/contact$"));
+    }
+
+    @Test
+    void discardLeavesTheForm() {
+        name().setValue("Ada");
+
+        aboutLink().click();
+
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Discard").click();
+
+        assertThat(page.locator("h1")).hasText("About");
+        assertThat(page).hasURL(java.util.regex.Pattern.compile(".*/about$"));
+    }
+}
